class Bowl:
    def __init__(self, n):
        self.n = n

    def __str__(self):
        return "装了 " + str(self.n) + " 条小鱼干"

    def __add__(self, other):
        return Bowl(self.n + other.n)

    def __eq__(self, other):
        return self.n == other.n


a = Bowl({n1})
b = Bowl({n2})
print(a + b)
print(a == b)
print(a == Bowl({n1}))
